import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易尚氏学 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易尚氏学 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/016.md","filePath":"zh/classics/shangshi/016.md"}'),h={name:"zh/classics/shangshi/016.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>阳性上升。阴性下降。乃阴在上。阳在下。故其气相接相交而为泰。泰通也。阳大阴小。爻在外曰往。在内曰来。故曰小往大来。泰寅月卦。阳长故亨。</p><p>彖曰。泰。小往大来吉亨。则是天地交而万物通也。上下交而其志同也。内阳而外阴。内健而外顺。内君子而外小人。君子道长。小人道消也。</p><p>阳上升。阴下降。故气交。坤为万物。为心志。交则万物气通。心志和合，故曰同。坤志象失传。易林屯之益云。心劳且忧。益互坤。以坤为心。又需之否云。毛羽憔悴。志如死灰。以否下坤为志为死。(详焦氏易诂易象补遗)内阳外阴。内健外顺。内君子外小人。将老氏宗旨。括尽无余。乾为君子。坤为小人。泰本候卦。阳长故阴消。按上经始乾坤。终水火。而以否泰为枢纽。明否泰剥复。皆天地自然之法象。循环之原理。君子所宜居而安也。静之象也。下经始咸恒。终既未济。而以损益。为枢纽。明吉凶失得。进退变化。全在人为。君子所以自强不息也。动之象也。而否泰损益。皆序于第十卦后者。数至十则盈。盈则变也。</p><p>象曰。天地交。泰。后以财成天地之道。辅相天地之宜。以左右民。</p><p>财裁同。释文荀作裁。释言疏。财裁音义并同。汉时臣工上疏。裁察每作财察。是其证。财成即裁成也。互震为左。互兑为右。坤为民。以左右民者。孔疏左右助也。以助养其民也。虞翻谓坤富称财非。</p><p>初九。拔茅茹。以其汇。征吉。</p><p>初应在四。四坤为茅茹。此象失传。易林剥之坤云。荻芝俱死。以坤为荻芝。又同人之屯云。蓬蒿代柱。大屋颠倒。屯互艮为屋为柱。互坤为蓬蒿。故坤亦为茅茹。茹菜属也。诗郑风茹藘在阪。前汉食货志。菜茹有畦。茅。说文菅也。茹与茅为二物。以其汇者。言茅与茹同拔。连类以及也。四有应。故征吉。</p><h3 id="象曰。拔茅征吉。志在外也。" tabindex="-1">象曰。拔茅征吉。志在外也。 <a class="header-anchor" href="#象曰。拔茅征吉。志在外也。" aria-label="Permalink to “象曰。拔茅征吉。志在外也。”">​</a></h3><p>初应在四。故曰志在外。外坤为心志。</p><p>九二。苞荒。用冯河。不遐遗。朋亡。得尚于中行。</p><p>释文云。荒本亦作巟。说文引同。许云水广。虞云大川也。晁氏云。汉易皆作巟彖辞巟河是一事。象数无田秽之荒。作荒始于王弼。按晁说是也。巟河为对文。王弼盖以坤为乱。改作荒。岂知坤为水。巟与河皆坤象也。苞今本作包。唐石经增改作苞。释文亦作苞。二应在五。五坤为大川。为河。言二必上升。有苞括大川。冯涉长河之势。断不以其辽远而不及也。阴以阳为朋。亡往也去也。朋往者。言二必往五。得尚居中正之位也。旧诂因坤水象及朋义失传。故无有得解者。(礼记少仪有亡而无疾。晋语请从此亡。注皆训为去。)</p><h3 id="象曰。苞荒。得尚于中行。以光大也。" tabindex="-1">象曰。苞荒。得尚于中行。以光大也。 <a class="header-anchor" href="#象曰。苞荒。得尚于中行。以光大也。" aria-label="Permalink to “象曰。苞荒。得尚于中行。以光大也。”">​</a></h3><p>五位尊。故曰光大。</p><p>九三。无平不陂。无往不复。艰贞无咎。勿恤其孚。于食有福。</p><p>陂倾也。复返也。阳息至三天地分。故曰平。然三居卦终。乾三云。终日乾乾。反复道也。言阳至三而盈。将反初成巽也。故曰无平不陂。无往不复。(巽陨落故倾)平陂往复。虽相循环。然三本当位。能艰贞自守。必无咎也。坤为忧恤。(临六三云。既忧之无咎。以坤为忧。易林大壮之损云。使母忧叹。以损互坤为忧也。详焦氏易诂。)三临之孚于群阴。故无恤。兑口为食。坤多故曰于食有福。乾为福也。</p><h3 id="象曰。无往不复。天地际也。" tabindex="-1">象曰。无往不复。天地际也。 <a class="header-anchor" href="#象曰。无往不复。天地际也。" aria-label="Permalink to “象曰。无往不复。天地际也。”">​</a></h3><p>广韵际边也。畔也。三应在上。三上居天地之极。极则返始。释平必陂。往必复之故也。宋衷曰。三位在乾极。应在坤极。以极诂际字。最为明晰。乃惠栋李道平等解释宋注。竟从小尔雅谓际者接也。天地际。即天地交接也。岂知乾极坤极，正释际义。际若为交接。与无往不复之义何与哉。失宋义矣。其它更无有能得解者。易理之失传。更甚于易象矣。</p><p>六四。翩翩。不富。以其邻不戒以孚。</p><p>震为飞。故曰翩翩。坤虚。故曰不富。以与也。震为邻。以其邻不戒以孚者。言四及五上。皆有应予。下孚于阳也。阴得阳应必吉。故曰不戒以孚。戒告诫也。震飞之象。易林屡用之。同人之坎云。出于幽谷。飞上乔木。以坎互震为飞也。证之易明夷初九云。明夷于飞。易即以震为飞。旧解以离为飞。若泰无离象也。</p><h3 id="象曰。翩翩不富。皆失实也。不戒以孚。中心愿也。" tabindex="-1">象曰。翩翩不富。皆失实也。不戒以孚。中心愿也。 <a class="header-anchor" href="#象曰。翩翩不富。皆失实也。不戒以孚。中心愿也。" aria-label="Permalink to “象曰。翩翩不富。皆失实也。不戒以孚。中心愿也。”">​</a></h3><p>坤为心志。(按益九五云有孚惠心。以互坤为心也。否初象云志在君也。以坤为志也。易林以坤为心志。证尤多。旧解皆以坎为心志。自得此象。凡易言心志者。始皆得解。)中心愿者。言阴喜应阳也。阳为实。失实。言无阳。</p><p>六五。帝乙归妹。以祉元吉。</p><p>震为帝。坤贞乙。故曰帝乙。兑为妹。震为归。妇人谓嫁曰归。归妹谓嫁妹也。正中爻震兑象也。祉福也。以祉元吉者。言二升五。五来二。(来二即归)各当其位。永为俪耦。故元吉也。象释曰中以行愿。即谓五愿归居二也。帝乙或谓为成汤。或谓为纣父。</p><h3 id="象曰。以祉元吉。中以行愿也。" tabindex="-1">象曰。以祉元吉。中以行愿也。 <a class="header-anchor" href="#象曰。以祉元吉。中以行愿也。" aria-label="Permalink to “象曰。以祉元吉。中以行愿也。”">​</a></h3><p>五位尊。故曰元吉。中以行愿。即谓五愿归二也。</p><p>上六。城复于隍。勿用师。自邑告命。</p><p>贞吝。复覆通。诗陶复陶穴。说文引作覆。是其证。艮为城。兑为隍。城池也。三至上艮覆。正当兑泽。故曰城覆于隍。九家云。城覆于隍。国政崩也。崩即谓艮覆。京房于复卦。朋来无咎。朋作崩。与此义同也。又易林归妹之泰云。倾夺我城。使家不宁。城倾。即谓泰三至上艮覆。释此爻也。坤为师。震为言。为告命。坤阴下降主退。故曰勿用。吴先生曰。邑挹之省文。挹损也。言自挹损其告命。如复世之下诏罪己也。贞吝。言卜问不吉。泰极将返否故也。</p><h3 id="象曰。城复于隍。其命乱也。" tabindex="-1">象曰。城复于隍。其命乱也。 <a class="header-anchor" href="#象曰。城复于隍。其命乱也。" aria-label="Permalink to “象曰。城复于隍。其命乱也。”">​</a></h3><p>坤为乱。其命乱者。言泰极返否。为天地自然之命运。无可避免。此命字与告命异。诸家混同之。非。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
